from pathlib import Path
import re
for p in sorted(Path('/workspace/evidence/training').glob('*/train.stdout')):
    lines=p.read_text(errors='replace').splitlines()
    print('\n',p.relative_to('/workspace'),'lines',len(lines))
    for i,raw in enumerate(lines):
        text=re.sub(r'\x1b\[[0-9;]*m','',raw)
        if any(w in text.lower() for w in ['error','traceback','exception','nan','inf','warning','resum','checkpoint','step:']):
            if 'step:' in text:
                print(i+1,'METRIC',text[:120])
            else:
                print(i+1,text[:1000])
    print('Last nonblank lines:')
    for i,raw in list(enumerate(lines))[-12:]:
        print(i+1,re.sub(r'\x1b\[[0-9;]*m','',raw)[:1600])
PY

